def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Generate F_2 up to F_125
F = {}
for k in range(2, 126):
    F[k] = fibonacci(k)

print(f"F_2 = {F[2]}")
