def fibonacci(k):
    if k <= 0:
        return 0
    if k == 1:
        return 1
    a, b = 0, 1
    for _ in range(k - 1):
        a, b = b, a + b
    return b

print(f"F_2 = {fibonacci(2)}")
print(f"F_10 = {fibonacci(10)}")
print(f"F_15 = {fibonacci(15)}")
print(f"F_125 = {fibonacci(125)}")
